    new_data <- data.frame(
      Age = rnorm(18), visit = rep(c(3, 2, 4), 6),
      Trt = rep(0:1, 9), count = rep(c(5, 17, 28), 6),
      patient = rep(1:6, each = 3), Exp = 4, volume = 0
    )
  )
  brms_setup("brmsfit-methods:921",
    up <- update(fit1, newdata = new_data, save_pars = save_pars(group = FALSE),
                 testmode = TRUE)
  )
  brms_port("brmsfit-methods:923", "divergence",
    paste0(
      "update(newdata =) returns a frmtmb_fit ; save_pars() was ",
      "dropped by the shim (D10) brms's class name; frmtmb objects ",
      "must NOT carry brms's class names (user decision, ",
      "2026-09-17, rule 2)"),
    expect_true(is(up, "brmsfit"))
  )
  brms_port("brmsfit-methods:924", "defect",
    paste0(
      "attr(up$data, 'data_name') is NULL: brms records the name ",
      "of the newdata argument on the frame it stores and frmtmb ",
