  brms_port("brmsfit-methods:927", "defect",
    paste0(
      "update(fit, data = new_data) refits on the new data where ",
      "brms refuses and demands newdata (dev/brms-suite-audit.md ",
      "section 7 contract 15; dev/brmsport-probe4.R)"),
    expect_error(update(fit1, data = new_data), "use argument 'newdata'")
  )
  brms_setup("brmsfit-methods:929",
    up <- update(fit1, formula = ~ . + I(exp(Age)), testmode = TRUE,
                 prior = set_prior("normal(0,10)"))
  )
  brms_port("brmsfit-methods:931", "divergence",
    paste0(
      "update() returns a frmtmb_fit brms's class name; frmtmb ",
      "objects must NOT carry brms's class names (user decision, ",
      "2026-09-17, rule 2)"),
    expect_true(is(up, "brmsfit"))
  )
  brms_setup("brmsfit-methods:932",
    up <- update(fit1, ~ . - Age + factor(Age),  testmode = TRUE)
  )
  brms_port("brmsfit-methods:933", "divergence",
    paste0(
      "update() returns a frmtmb_fit brms's class name; frmtmb ",
      "objects must NOT carry brms's class names (user decision, ",
      "2026-09-17, rule 2)"),
    expect_true(is(up, "brmsfit"))
  )
  brms_setup("brmsfit-methods:935",
    up <- update(fit1, formula = ~ . + I(exp(Age)), newdata = new_data,
                 sample_prior = FALSE, testmode = TRUE)
  )
  brms_port("brmsfit-methods:937", "divergence",
    paste0(
      "update() returns a frmtmb_fit brms's class name; frmtmb ",
      "objects must NOT carry brms's class names (user decision, ",
      "2026-09-17, rule 2)"),
    expect_true(is(up, "brmsfit"))
  )
  brms_port("brmsfit-methods:938", "defect",
    paste0(
      "a formula update naming a variable the data lacks dies with ",
      "R's object 'wrong_var' not found, not 'New variables found'"),
    expect_error(update(fit1, formula. = ~ . + wrong_var),
                 "New variables found: 'wrong_var'")
  )
  brms_setup("brmsfit-methods:941",
    up <- update(fit1, save_pars = save_pars(group = FALSE), testmode = TRUE)
  )
  brms_port("brmsfit-methods:942", "divergence",
    paste0(
      "update() returns a frmtmb_fit brms's class name; frmtmb ",
      "objects must NOT carry brms's class names (user decision, ",
      "2026-09-17, rule 2)"),
    expect_true(is(up, "brmsfit"))
  )
  brms_setup("brmsfit-methods:944",
    up <- update(fit3, save_pars = save_pars(latent = FALSE), testmode = TRUE)
  )
  brms_port("brmsfit-methods:945", "divergence",
    paste0(
      "update() returns a frmtmb_fit brms's class name; frmtmb ",
      "objects must NOT carry brms's class names (user decision, ",
      "2026-09-17, rule 2)"),
    expect_true(is(up, "brmsfit"))
  )
  brms_setup("brmsfit-methods:948",
    up <- update(fit2, algorithm = "fullrank", testmode = TRUE)
  )
  brms_port("brmsfit-methods:949", "divergence",
    paste0(
      "update() returns a frmtmb_fit brms's class name; frmtmb ",
      "objects must NOT carry brms's class names (user decision, ",
      "2026-09-17, rule 2)"),
    expect_true(is(up, "brmsfit"))
  )
  brms_setup("brmsfit-methods:951",
    up <- update(fit2, formula. = bf(. ~ ., a + b ~ 1, nl = TRUE),
                 testmode = TRUE)
  )
  brms_port("brmsfit-methods:953", "defect",
    paste0(
      "update(fit2, formula. = bf(. ~ ., a + b ~ 1, nl = TRUE)) is ",
      "refused: the dot does not carry the old nonlinear body, so ",
      "a and b are 'not used'"),
    expect_true(is(up, "brmsfit"))
  )
  brms_setup("brmsfit-methods:954",
    up <- update(fit2, formula. = bf(count ~ a + b, nl = TRUE), testmode = TRUE)
  )
  brms_port("brmsfit-methods:955", "defect",
    paste0(
      "update(fit2, formula. = bf(count ~ a + b, nl = TRUE)) is ",
      "refused for having no parameter formulas; brms keeps fit2's"),
    expect_true(is(up, "brmsfit"))
  )
  brms_setup("brmsfit-methods:956",
    up <- update(fit3, family = acat(), testmode = TRUE)
  )
  brms_port("brmsfit-methods:957", "divergence",
    paste0(
      "update(family = acat()) returns a frmtmb_fit brms's class ",
      "name; frmtmb objects must NOT carry brms's class names ",
      "(user decision, 2026-09-17, rule 2)"),
    expect_true(is(up, "brmsfit"))
  )
  brms_setup("brmsfit-methods:958",
    up <- update(fit3, bf(~., family = acat()), testmode = TRUE)
  )
  brms_port("brmsfit-methods:959", "defect",
    paste0(
      "update(fit3, bf(~ ., family = acat())) is refused as a ",
      "formula with no response; brms reads the one-sided dot as ",
      "the old formula"),
    expect_true(is(up, "brmsfit"))
  )
})

test_that("variables has reasonable ouputs", {
  brms_port("brmsfit-methods:978", "divergence",
    paste0(
      "variables(fit) lists an ML fit's parameters; simo_, r_ and ",
      "s_ draws and prior_ and lp__ are posterior or Stan ",
      "quantities (D5, D10; dev/brmsnames-findings.md A10)"),
    expect_true(all(
      c("b_Intercept", "bsp_moExp", "ar[1]", "cor_visit__Intercept__Trt1",
        "nu", "simo_moExp1[2]", "r_visit[4,Trt1]", "s_sAge_1[8]",
        "prior_sd_visit", "prior_cor_visit", "lp__") %in%
        variables(fit1)
    ))
  )
  brms_port("brmsfit-methods:984", "divergence",
    paste0(
      "variables(fit2) has brms's b_, sd_ and cor_ names; the r_ ",
      "and prior_ names are posterior or Stan quantities (D5, D10)"),
    expect_true(all(
      c("b_a_Intercept", "b_b_Age", "sd_patient__b_Intercept",
        "cor_patient__a_Intercept__b_Intercept",
        "r_patient__a[1,Intercept]", "r_patient__b[4,Intercept]",
        "prior_b_a") %in%
        variables(fit2)
    ))
  )
  brms_port("brmsfit-methods:991", "cannot transfer",
    paste0(
      "lscale_volume_gpAgeTrt0 needs gp(Age, by = Trt), which ",
      "frmtmb's gp() does not take (D8)"),
    expect_true(all(
      c("lscale_volume_gpAgeTrt0", "lscale_volume_gpAgeTrt1") %in%
        variables(fit6)
    ))
  )
  brms_port("brmsfit-methods:995", "defect",
    paste0(
      "parnames() is brms's live spelling of variables(); ",
      "frmtmb.sample defines parnames() and refuses it, core has ",
      "none (dev/brms-suite-audit.md section 7 contract 14)"),
    expect_equal(variables(fit3), SW(parnames(fit3)))
  )
})

